import subprocess,json,time,os
from pathlib import Path
p=Path('.lake/source-units/callback-diagnostic')
docker=['env','-u','DOCKER_HOST','-u','DOCKER_CONTEXT','-u','DOCKER_TLS','-u','DOCKER_TLS_VERIFY','-u','DOCKER_CERT_PATH','docker','--host=unix:///var/run/docker.sock']
cmd=docker+['create','--name','source-units-callback-baseline','--network=none','--memory=12g','--memory-swap=12g','--pids-limit=256','--user=1000:1000','--cap-drop=ALL','--mount','type=bind,src=/workspace,dst=/workspace','--mount','type=bind,src=/workspace/.setup/tools/lean-4.24.0-linux,dst=/opt/source-units-toolchain,readonly','--mount','type=bind,src='+str((p/'lean').resolve())+',dst=/workspace/.setup/tools/lean-4.24.0-linux/bin/lean,readonly','--mount','type=bind,src='+str((p/'CallbackStrategy.baseline.lean').resolve())+',dst=/workspace/solidity-lean-source-units/Solidity/Examples/Tactics/CallbackStrategy.lean,readonly','--workdir',str(Path.cwd()),'-e','LEAN_NUM_THREADS=1','-e','XDG_CACHE_HOME='+str(Path('.lake/source-units/docker-gate/cache').resolve()),'-e','PATH=/workspace/.setup/tools/lean-4.24.0-linux/bin:/usr/bin:/bin','debian@sha256:89c1ea91e897f0fe0a3731595330bc45b8bdef4047464a07116f891a94054b31','sh',str(p/'gates.sh')]
container=subprocess.check_output(cmd,text=True).strip();(p/'command.json').write_text(json.dumps(cmd,indent=2)+'\n')
start=time.monotonic(); peak=0; minhost=2**64; minparent=2**64;stop=None;cg=None;last={}
with (p/'container.log').open('w') as log,(p/'samples.jsonl').open('w') as samples:
 proc=subprocess.Popen(docker+['start','-a',container],stdout=log,stderr=subprocess.STDOUT)
 while proc.poll() is None:
  host=int(next(x.split()[1] for x in Path('/proc/meminfo').read_text().splitlines() if x.startswith('MemAvailable:')))*1024
  parentmax=int(Path('/sys/fs/cgroup/memory.max').read_text());parent=int(Path('/sys/fs/cgroup/memory.current').read_text());minhost=min(minhost,host);minparent=min(minparent,parentmax-parent)
  if cg is None:
   cg=next((x for x in Path('/sys/fs/cgroup').rglob('memory.peak') if container in str(x)),None)
  if cg is not None:
   try:
    root=cg.parent;peak=max(peak,int(cg.read_text()));last={'current':int((root/'memory.current').read_text()),'peak':peak,'max':(root/'memory.max').read_text().strip(),'swapMax':(root/'memory.swap.max').read_text().strip(),'events':(root/'memory.events').read_text()}
   except FileNotFoundError:pass
  sample={'elapsed':time.monotonic()-start,'hostAvailableBytes':host,'parentHeadroomBytes':parentmax-parent,'task':last};samples.write(json.dumps(sample)+'\n');samples.flush()
  if min(host,parentmax-parent)<2*1024**3:
   stop='OS headroom below2GiB; task-only container stop';(p/'stop-sample.json').write_text(json.dumps(sample,indent=2));subprocess.run(docker+['kill',container],check=True);break
  time.sleep(.25)
 proc.wait()
state=json.loads(subprocess.check_output(docker+['inspect',container]))[0]
record={'command':cmd,'exitCode':proc.returncode,'elapsedSeconds':time.monotonic()-start,'resourceStop':stop,'hostMinimumAvailableBytes':minhost,'parentMinimumHeadroomBytes':minparent,'sampledTaskMemoryPeakBytes':peak if cg else None,'lastTaskCounters':last,'containerState':state['State'],'limits':{k:state['HostConfig'][k] for k in ['Memory','MemorySwap','PidsLimit','NetworkMode']},'headroomThresholdBytes':2*1024**3,'method':'kernel task cgroup12GiB/swap0; parent16GiB and host available both monitored from before start; Lean serial -j1 timeout180; no shared-host12GiB reserve'}
(p/'terminal.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record));raise SystemExit(proc.returncode if not stop else 137)
